'use client';

import { useEffect, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { ConsentBanner, SettingsLink } from './consent-banner';
import {
  SITE_NAME,
  STORAGE_KEY,
  type CookieConsent,
  type OptionalCategoryId,
} from './data';
import { PreferencesDialog } from './preferences-dialog';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  type ConsentAction,
} from './session';
import { SitePage } from './site-page';

export type { CookieConsent } from './data';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function isConsent(value: unknown): value is CookieConsent {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const hasNecessary = 'necessary' in value && value.necessary === true;
  const hasPreferences =
    'preferences' in value && typeof value.preferences === 'boolean';
  const hasAnalytics =
    'analytics' in value && typeof value.analytics === 'boolean';
  const hasMarketing =
    'marketing' in value && typeof value.marketing === 'boolean';
  const hasOptional = hasPreferences && hasAnalytics;
  return hasNecessary && hasOptional && hasMarketing;
}

/** Storage can be refused (private windows, blocked site data): the choice then lives in memory only. */
function readConsent(key: string) {
  try {
    const raw = window.localStorage.getItem(key);
    if (raw === null) {
      return null;
    }
    const parsed: unknown = JSON.parse(raw);
    if (isConsent(parsed)) {
      return parsed;
    }
    return null;
  } catch {
    return null;
  }
}

function writeConsent(key: string, consent: CookieConsent) {
  try {
    const raw = JSON.stringify(consent);
    window.localStorage.setItem(key, raw);
  } catch {
    return;
  }
}

/** Once a choice exists the banner is gone, so the focus goes back to the way to it. */
function returnFocusOf(consent: CookieConsent | null) {
  if (consent) {
    return '[data-cookie-settings]';
  }
  return '[data-customize]';
}

export type Legal02Props = {
  /** Called with every choice a person saves. The demonstration never calls it. */
  onChange?: (consent: CookieConsent) => void;
  /** Keeps the choice in this browser and starts from it on the next visit. */
  persist?: boolean;
  storageKey?: string;
};

export default function Legal02({
  onChange,
  persist = false,
  storageKey = STORAGE_KEY,
}: Legal02Props) {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
    takeOver,
  } = useSession(SESSION);
  const shouldReduceMotion = usePrefersReducedMotion();
  const [hasReadStorage, setHasReadStorage] = useState(!persist);
  const hasNoChoice = state.consent === null;
  const isBannerShown = hasNoChoice && hasReadStorage;
  const isLinkShown = state.consent !== null;
  const message = spokenUnless(isAutoplaying, state.spoken);
  const canReplay = isFinished && !isAutoplaying;

  /**
   * Under reduced motion the session puts its resting state in place on the next task, which
   * would hide a stored choice: the choice is read and put back after it, whenever that setting
   * changes. Until it is read the banner waits, so a returning visitor never sees it flash.
   */
  useEffect(() => {
    if (!persist) {
      return;
    }
    const timer = setTimeout(() => {
      setHasReadStorage(true);
      const stored = readConsent(storageKey);
      if (!stored) {
        return;
      }
      act({ type: 'restored', consent: stored });
      takeOver();
    }, 0);
    return () => clearTimeout(timer);
  }, [persist, storageKey, act, takeOver, shouldReduceMotion]);

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  function decide(action: ConsentAction) {
    const after = reducer(state, action);
    act(action);
    const consent = after.consent;
    if (!consent) {
      return;
    }
    onChange?.(consent);
    if (persist) {
      writeConsent(storageKey, consent);
    }
    focusLater('[data-cookie-settings]');
  }

  function openDialog() {
    act({ type: 'dialogOpened' });
    focusLater('[data-dialog-title]');
  }

  function closeDialog() {
    act({ type: 'dialogClosed' });
    focusLater(returnFocusOf(state.consent));
  }

  function switchCategory(id: OptionalCategoryId, isOn: boolean) {
    act({ type: 'categorySwitched', id, isOn });
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container relative isolate flex h-dvh min-h-[34rem] w-full flex-col overflow-hidden'
      >
        <div
          inert={state.isDialogOpen}
          className='flex min-h-0 flex-1 flex-col'
        >
          <div
            role='region'
            aria-label={`${SITE_NAME} guide`}
            tabIndex={0}
            className='focus-visible:ring-ring/25 min-h-0 flex-1 overflow-y-auto outline-none focus-visible:ring-[3px] focus-visible:ring-inset'
          >
            <SitePage
              aside={
                <ReplayButton
                  isShown={canReplay}
                  onReplay={restart}
                  label='Replay'
                />
              }
            />
          </div>
          <div className='pointer-events-none absolute inset-x-0 bottom-0 z-20 flex justify-center p-4'>
            <ConsentBanner
              isShown={isBannerShown}
              pressed={pressed}
              onRejectAll={() => decide({ type: 'rejectedAll' })}
              onAcceptAll={() => decide({ type: 'acceptedAll' })}
              onCustomize={openDialog}
            />
          </div>
          <div className='pointer-events-none absolute start-0 bottom-0 z-20 p-3'>
            <SettingsLink
              isShown={isLinkShown}
              isPressed={pressed === 'settings'}
              onOpen={openDialog}
            />
          </div>
        </div>
        <PreferencesDialog
          isOpen={state.isDialogOpen}
          draft={state.draft}
          pressed={pressed}
          onSwitch={switchCategory}
          onAcceptAll={() => decide({ type: 'acceptedAll' })}
          onRejectAll={() => decide({ type: 'rejectedAll' })}
          onSave={() => decide({ type: 'choicesSaved' })}
          onClose={closeDialog}
        />
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { CookieIcon } from '@/registry/ndeko/lib/icons';
import {
  EASE_OUT_STRONG,
  fadePresence,
} from '@/registry/ndeko/lib/motion-presets';
import { Button } from '@/registry/ndeko/ui/button';

import { SITE_NAME } from './data';

const BANNER_PRESENCE = {
  initial: { opacity: 0, y: 12 },
  animate: { opacity: 1, y: 0 },
  exit: {
    opacity: 0,
    y: 8,
    transition: { duration: 0.2, ease: EASE_OUT_STRONG },
  },
  transition: { duration: 0.25, ease: EASE_OUT_STRONG },
};

function bannerPresenceOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return fadePresence();
  }
  return BANNER_PRESENCE;
}

type ConsentBannerProps = {
  isShown: boolean;
  pressed: string | null;
  onRejectAll: () => void;
  onAcceptAll: () => void;
  onCustomize: () => void;
};

/** It never covers the page: no backdrop, the article under it still scrolls and reads. */
export function ConsentBanner({
  isShown,
  pressed,
  onRejectAll,
  onAcceptAll,
  onCustomize,
}: ConsentBannerProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const presence = bannerPresenceOf(shouldReduceMotion);

  return (
    <AnimatePresence initial={false}>
      {isShown && (
        <motion.div
          key='banner'
          role='region'
          aria-label='Cookie choices'
          className='surface-raised pointer-events-auto flex w-full max-w-2xl flex-col gap-3 rounded-xl p-4 @2xl:flex-row @2xl:items-center @2xl:gap-6'
          {...presence}
        >
          <p className='min-w-0 flex-1 text-[13px] text-pretty'>
            <span className='font-medium'>{`Cookies on ${SITE_NAME}.`}</span> We
            use the ones the site needs to work. With your yes, we also count
            visits and remember your reading preferences.
          </p>
          <div className='flex flex-wrap items-center gap-2'>
            <Button
              type='button'
              variant='outline'
              size='sm'
              data-reject-all
              onClick={onRejectAll}
              className={pressedQuietOf(pressed === 'reject')}
            >
              Reject all
            </Button>
            <Button
              type='button'
              variant='outline'
              size='sm'
              onClick={onAcceptAll}
              className={pressedQuietOf(pressed === 'accept')}
            >
              Accept all
            </Button>
            <Button
              type='button'
              variant='ghost'
              size='sm'
              data-customize
              onClick={onCustomize}
              className={pressedQuietOf(pressed === 'customize')}
            >
              Customize
            </Button>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

type SettingsLinkProps = {
  isShown: boolean;
  isPressed: boolean;
  onOpen: () => void;
};

/** What the banner leaves behind once a choice is saved: the way back to it. */
export function SettingsLink({
  isShown,
  isPressed,
  onOpen,
}: SettingsLinkProps) {
  const fade = fadePresence();

  return (
    <AnimatePresence initial={false}>
      {isShown && (
        <motion.div key='settings' className='pointer-events-auto' {...fade}>
          <Button
            type='button'
            variant='ghost'
            size='sm'
            data-cookie-settings
            onClick={onOpen}
            className={pressedQuietOf(isPressed)}
          >
            <CookieIcon />
            Cookie settings
          </Button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

'use client';

import { useId } from 'react';

import {
  pressedQuietOf,
  pressedSolidOf,
} from '@/registry/ndeko/lib/demonstration';
import { LockIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Switch } from '@/registry/ndeko/ui/switch';

import {
  NECESSARY,
  OPTIONAL_CATEGORIES,
  SITE_NAME,
  type Category,
  type OptionalCategoryId,
} from './data';
import type { ConsentDraft } from './session';

function layerOf(isOpen: boolean) {
  if (isOpen) {
    return undefined;
  }
  return 'pointer-events-none';
}

function backdropOf(isOpen: boolean) {
  if (isOpen) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

function panelOf(isOpen: boolean) {
  if (isOpen) {
    return 'scale-100 opacity-100';
  }
  return 'scale-95 opacity-0 duration-150';
}

type CategoryRowProps = {
  category: Category;
  isOn: boolean;
  isLocked: boolean;
  isPressed: boolean;
  /** A locked category takes no change. */
  onSwitch?: (isOn: boolean) => void;
};

function CategoryRow({
  category,
  isOn,
  isLocked,
  isPressed,
  onSwitch,
}: CategoryRowProps) {
  const nameId = useId();
  const lineId = useId();

  return (
    <li className='flex items-start gap-4 py-3'>
      <div className='flex min-w-0 flex-1 flex-col gap-1'>
        <p
          id={nameId}
          className='flex flex-wrap items-center gap-2 text-[13px] font-medium'
        >
          {category.name}
          {isLocked && (
            <Badge variant='secondary'>
              <LockIcon />
              Always on
            </Badge>
          )}
        </p>
        <p id={lineId} className='text-muted-foreground text-xs text-pretty'>
          {category.line}
        </p>
      </div>
      <span
        className={cn(
          'mt-0.5 inline-flex rounded-full transition-[scale] duration-150 ease-(--ease-out-strong)',
          pressedQuietOf(isPressed)
        )}
      >
        <Switch
          checked={isOn}
          disabled={isLocked}
          onCheckedChange={onSwitch}
          aria-labelledby={nameId}
          aria-describedby={lineId}
        />
      </span>
    </li>
  );
}

type PreferencesDialogProps = {
  isOpen: boolean;
  draft: ConsentDraft;
  pressed: string | null;
  onSwitch: (id: OptionalCategoryId, isOn: boolean) => void;
  onAcceptAll: () => void;
  onRejectAll: () => void;
  onSave: () => void;
  onClose: () => void;
};

/**
 * Drawn inside the block, so it never covers anything but the page it belongs to. While it is open
 * the page under it is inert, so the keyboard stays in the dialog until it closes.
 */
export function PreferencesDialog({
  isOpen,
  draft,
  pressed,
  onSwitch,
  onAcceptAll,
  onRejectAll,
  onSave,
  onClose,
}: PreferencesDialogProps) {
  const titleId = useId();
  const lineId = useId();

  function closeOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key !== 'Escape') {
      return;
    }
    event.preventDefault();
    onClose();
  }

  return (
    <div
      inert={!isOpen}
      onKeyDown={closeOnEscape}
      className={cn('absolute inset-0 z-30', layerOf(isOpen))}
    >
      <button
        type='button'
        tabIndex={-1}
        aria-label='Close cookie preferences'
        onClick={onClose}
        className={cn(
          'absolute inset-0 cursor-default bg-black/40 backdrop-blur-xs transition-opacity duration-200',
          backdropOf(isOpen)
        )}
      />
      <div
        role='dialog'
        aria-modal='true'
        aria-labelledby={titleId}
        aria-describedby={lineId}
        className={cn(
          'bg-card text-card-foreground hairline-ring ring-border absolute top-1/2 left-1/2 flex max-h-[calc(100%-2rem)] w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 flex-col gap-4 overflow-x-hidden overflow-y-auto rounded-2xl p-5 shadow-xl shadow-black/8 transition-[opacity,scale] duration-200 ease-(--ease-out-strong) @md:p-6',
          panelOf(isOpen)
        )}
      >
        <div className='flex flex-col gap-1.5 pe-8'>
          <h2
            id={titleId}
            data-dialog-title
            tabIndex={-1}
            className='text-lg leading-tight font-semibold outline-none'
          >
            Cookie preferences
          </h2>
          <p
            id={lineId}
            className='text-muted-foreground text-[13px] text-pretty'
          >
            {`Choose what ${SITE_NAME} may keep on this device. You can change it any time from Cookie settings at the foot of the page.`}
          </p>
        </div>
        <ul className='hairline-divide-y divide-border flex flex-col'>
          <CategoryRow category={NECESSARY} isOn isLocked isPressed={false} />
          {OPTIONAL_CATEGORIES.map((category) => (
            <CategoryRow
              key={category.id}
              category={category}
              isOn={draft[category.id]}
              isLocked={false}
              isPressed={pressed === `switch-${category.id}`}
              onSwitch={(isOn) => onSwitch(category.id, isOn)}
            />
          ))}
        </ul>
        <div className='flex flex-wrap items-center justify-end gap-2'>
          <Button
            type='button'
            variant='outline'
            onClick={onRejectAll}
            className={pressedQuietOf(pressed === 'reject-in-dialog')}
          >
            Reject all
          </Button>
          <Button type='button' variant='outline' onClick={onAcceptAll}>
            Accept all
          </Button>
          <Button
            type='button'
            onClick={onSave}
            className={pressedSolidOf(pressed === 'save')}
          >
            Save choices
          </Button>
        </div>
        <Button
          type='button'
          variant='ghost'
          size='icon-sm'
          aria-label='Close'
          onClick={onClose}
          className='text-muted-foreground absolute top-3 right-3'
        >
          <XIcon />
        </Button>
      </div>
    </div>
  );
}

import { CompanyMark } from '@/registry/ndeko/ui/company-mark';

import { ARTICLE, SITE_NAME } from './data';

type SitePageProps = {
  aside?: React.ReactNode;
};

/** The page the banner sits on: a guide on the site of a fictional product, there to be read. */
export function SitePage({ aside }: SitePageProps) {
  return (
    <div className='flex flex-col'>
      <header className='hairline-b border-border flex h-14 shrink-0 items-center gap-2.5 px-4 @xl:px-8'>
        <CompanyMark seed={SITE_NAME} size='lg' />
        <span className='text-sm font-semibold'>{SITE_NAME}</span>
        <span className='text-muted-foreground ms-3 hidden text-[13px] @md:inline'>
          {ARTICLE.section}
        </span>
        <span className='ms-auto flex items-center'>{aside}</span>
      </header>
      <article className='mx-auto flex w-full max-w-2xl flex-col gap-5 px-4 pt-10 pb-56 @xl:px-8 @xl:pt-14'>
        <div className='flex flex-col gap-2'>
          <p className='text-primary-ink text-xs font-medium'>
            {ARTICLE.section}
          </p>
          <h1 className='text-2xl font-semibold text-balance @xl:text-3xl'>
            {ARTICLE.title}
          </h1>
          <p className='text-muted-foreground text-xs'>{ARTICLE.meta}</p>
        </div>
        {ARTICLE.paragraphs.map((paragraph) => (
          <p
            key={paragraph}
            className='text-muted-foreground text-base leading-relaxed text-pretty'
          >
            {paragraph}
          </p>
        ))}
      </article>
    </div>
  );
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import type { CookieConsent, OptionalCategoryId } from './data';

export type ConsentDraft = Record<OptionalCategoryId, boolean>;

export type ConsentState = {
  /** The saved choice, or null while the visitor has not answered. */
  consent: CookieConsent | null;
  draft: ConsentDraft;
  isDialogOpen: boolean;
  spoken: string;
};

export type ConsentAction =
  | { type: 'dialogOpened' }
  | { type: 'dialogClosed' }
  | { type: 'categorySwitched'; id: OptionalCategoryId; isOn: boolean }
  | { type: 'acceptedAll' }
  | { type: 'rejectedAll' }
  | { type: 'choicesSaved' }
  | { type: 'restored'; consent: CookieConsent };

type Step = SessionStep<ConsentState, ConsentAction>;

const NOTHING_OPTIONAL: ConsentDraft = {
  preferences: false,
  analytics: false,
  marketing: false,
};

const EVERYTHING: ConsentDraft = {
  preferences: true,
  analytics: true,
  marketing: true,
};

export const INITIAL: ConsentState = {
  consent: null,
  draft: NOTHING_OPTIONAL,
  isDialogOpen: false,
  spoken: '',
};

function consentOf(draft: ConsentDraft): CookieConsent {
  return { necessary: true, ...draft };
}

function draftOf(consent: CookieConsent | null): ConsentDraft {
  if (!consent) {
    return NOTHING_OPTIONAL;
  }
  return {
    preferences: consent.preferences,
    analytics: consent.analytics,
    marketing: consent.marketing,
  };
}

function allowedCountOf(draft: ConsentDraft) {
  const allowed = Object.values(draft).filter(Boolean);
  return allowed.length;
}

function savedLineOf(draft: ConsentDraft) {
  const count = allowedCountOf(draft);
  if (count === 0) {
    return 'Saved: only necessary cookies';
  }
  if (count === 1) {
    return 'Saved: necessary cookies and 1 more kind';
  }
  return `Saved: necessary cookies and ${count} more kinds`;
}

/** The dialog opens on the choice already saved, or on nothing but the necessary ones. */
function dialogOpened(state: ConsentState): ConsentState {
  return {
    ...state,
    isDialogOpen: true,
    draft: draftOf(state.consent),
    spoken: 'Cookie preferences opened',
  };
}

function decided(
  state: ConsentState,
  draft: ConsentDraft,
  spoken: string
): ConsentState {
  return {
    ...state,
    consent: consentOf(draft),
    draft,
    isDialogOpen: false,
    spoken,
  };
}

export function reducer(
  state: ConsentState,
  action: ConsentAction
): ConsentState {
  switch (action.type) {
    case 'dialogOpened':
      return dialogOpened(state);
    case 'dialogClosed':
      return { ...state, isDialogOpen: false, spoken: '' };
    case 'categorySwitched': {
      const draft = { ...state.draft, [action.id]: action.isOn };
      return { ...state, draft };
    }
    case 'acceptedAll':
      return decided(state, EVERYTHING, 'Saved: all cookies');
    case 'rejectedAll':
      return decided(state, NOTHING_OPTIONAL, 'Saved: only necessary cookies');
    case 'choicesSaved':
      return decided(state, state.draft, savedLineOf(state.draft));
    case 'restored':
      return {
        ...state,
        consent: action.consent,
        draft: draftOf(action.consent),
      };
  }
}

/**
 * A visitor opens Customize, allows two kinds and saves, then comes back from Cookie settings and
 * refuses everything with one press: rejecting takes no more than accepting.
 */
export const SCRIPT: Step[] = [
  {
    after: 1600,
    by: 'demo',
    press: 'customize',
    action: { type: 'dialogOpened' },
  },
  {
    after: 1300,
    by: 'demo',
    press: 'switch-analytics',
    action: { type: 'categorySwitched', id: 'analytics', isOn: true },
  },
  {
    after: 900,
    by: 'demo',
    press: 'switch-preferences',
    action: { type: 'categorySwitched', id: 'preferences', isOn: true },
  },
  {
    after: 1300,
    by: 'demo',
    press: 'save',
    action: { type: 'choicesSaved' },
  },
  {
    after: 2600,
    by: 'demo',
    press: 'settings',
    action: { type: 'dialogOpened' },
  },
  {
    after: 1700,
    by: 'demo',
    press: 'reject-in-dialog',
    action: { type: 'rejectedAll' },
  },
];

/** Under reduced motion the banner waits with its three answers, as a visitor first sees it. */
export const RESTING = INITIAL;

export const LOOP_AFTER_MS = 3000;

export type OptionalCategoryId = 'preferences' | 'analytics' | 'marketing';

export type CategoryId = 'necessary' | OptionalCategoryId;

/** What the visitor allowed. Necessary cookies cannot be refused, so they are always true. */
export type CookieConsent = {
  necessary: true;
  preferences: boolean;
  analytics: boolean;
  marketing: boolean;
};

export type Category = {
  id: CategoryId;
  name: string;
  line: string;
};

export const SITE_NAME = 'Brightloom';

export const STORAGE_KEY = 'brightloom-cookie-consent';

export const NECESSARY: Category = {
  id: 'necessary',
  name: 'Necessary',
  line: 'Keep you signed in, protect the forms and remember this choice. The site does not work without them, so they stay on.',
};

export const OPTIONAL_CATEGORIES: (Category & { id: OptionalCategoryId })[] = [
  {
    id: 'preferences',
    name: 'Preferences',
    line: 'Remember your language, your text size and the guides you saved',
  },
  {
    id: 'analytics',
    name: 'Analytics',
    line: 'Count visits and the pages people leave from, without your name',
  },
  {
    id: 'marketing',
    name: 'Marketing',
    line: 'Let partners show you ads based on what you read here',
  },
];

export const ARTICLE = {
  section: 'Guides',
  title: 'Plan the week on one board',
